import{_ as a,o as t,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const p=JSON.parse('{"title":"💬 03 · 自然语言处理 NLP","description":"","frontmatter":{},"headers":[],"relativePath":"04-算法岗-传统深度学习/03-自然语言处理NLP.md","filePath":"04-算法岗-传统深度学习/03-自然语言处理NLP.md","lastUpdated":1786806808000}'),l={name:"04-算法岗-传统深度学习/03-自然语言处理NLP.md"};function n(i,o,s,d,c,h){return t(),e("div",null,[...o[0]||(o[0]=[r('<h1 id="💬-03-·-自然语言处理-nlp" tabindex="-1">💬 03 · 自然语言处理 NLP <a class="header-anchor" href="#💬-03-·-自然语言处理-nlp" aria-label="Permalink to &quot;💬 03 · 自然语言处理 NLP&quot;">​</a></h1><blockquote><p>大模型之前，NLP 是怎么做的；这些基础仍是理解 LLM 的前提。</p></blockquote><hr><h2 id="一、词表示演进" tabindex="-1">一、词表示演进 <a class="header-anchor" href="#一、词表示演进" aria-label="Permalink to &quot;一、词表示演进&quot;">​</a></h2><ul><li><strong>One-hot</strong>：稀疏、无语义</li><li><strong>词袋/TF-IDF</strong>：统计特征</li><li><strong>Word2Vec / GloVe</strong>：稠密向量，捕捉语义相似（但一词多义难）</li><li><strong>ELMo / BERT 上下文向量</strong>：一词一向量随上下文变</li></ul><h2 id="二、序列建模" tabindex="-1">二、序列建模 <a class="header-anchor" href="#二、序列建模" aria-label="Permalink to &quot;二、序列建模&quot;">​</a></h2><ul><li><strong>RNN</strong>：时序建模，但梯度消失/难并行</li><li><strong>LSTM/GRU</strong>：门控缓解长程依赖</li><li><strong>Seq2Seq + Attention</strong>（Bahdanau）：解码时关注编码端相关位置 —— <strong>Transformer 注意力的前身</strong></li><li><strong>CRF</strong>：序列标注（NER/分词）常用</li></ul><h2 id="三、预训练时代-见-01-llm-详述" tabindex="-1">三、预训练时代（见 01-LLM 详述） <a class="header-anchor" href="#三、预训练时代-见-01-llm-详述" aria-label="Permalink to &quot;三、预训练时代（见 01-LLM 详述）&quot;">​</a></h2><ul><li>BERT（MLM，理解）、GPT（CLM，生成）、ELMo 等</li><li>本篇只补「大模型之前」的基础，大模型细节见 <code>01-算法岗-AIGC与LLM</code></li></ul><h2 id="四、经典-nlp-任务" tabindex="-1">四、经典 NLP 任务 <a class="header-anchor" href="#四、经典-nlp-任务" aria-label="Permalink to &quot;四、经典 NLP 任务&quot;">​</a></h2><ul><li>分类（情感）、序列标注（NER/分词）、抽取（关系/事件）、生成（翻译/摘要）、匹配（检索/问答）</li></ul><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：Word2Vec 和 BERT embedding 本质区别？</strong></p><blockquote><p>Word2Vec 是静态（一词一向量）；BERT 是上下文动态（同词不同上下文向量不同），更好处理多义。</p></blockquote><p><strong>Q2：Attention 在 Transformer 之前就有吗？</strong></p><blockquote><p>有。机器翻译的 Bahdanau Attention 已用于 Seq2Seq，Transformer 把它发扬为唯一机制并去掉 RNN。</p></blockquote><p><strong>Q3：为什么 RNN 难训练长序列？</strong></p><blockquote><p>时序依赖导致梯度随时间连乘，易消失/爆炸；且无法并行。Transformer 用自注意力一次性建模全局依赖并并行。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-强化学习RL">04-强化学习 RL</a></p>',20)])])}const _=a(l,[["render",n]]);export{p as __pageData,_ as default};
